class Solution:
    def maxArithmeticLength(self, nums: List[int]) -> int:
        n = len(nums)
        left = [1] * n
        right = [1] * n
        for i in range(1, n):
            if i > 1 and nums[i] - nums[i-1] == nums[i-1] - nums[i-2]:
                left[i] = left[i-1] + 1
        for i in range(n - 2, -1, -1):
            if i < n - 2 and nums[i+1] - nums[i] == nums[i+2] - nums[i+1]:
                right[i] = right[i+1] + 1
        ans = max(left)
        for i in range(1, n - 1):
            L, R = left[i-1], right[i+1]
            dl = nums[i-1] - nums[i-2] if L >= 2 else None
            dr = nums[i+2] - nums[i+1] if R >= 2 else None
            if dl is not None and dr is not None:
                cand = L + R + 1 if dl == dr else max(L + 1, R + 1)
            elif dl is not None:
                cand = L + 1
                if nums[i+1] - nums[i-1] == 2 * dl: cand = max(cand, L + 2)
            elif dr is not None:
                cand = R + 1
                if nums[i+1] - nums[i-1] == 2 * dr: cand = max(cand, R + 2)
            else:
                cand = 3
            ans = max(ans, cand)
        ans = max(ans, right[1] + 1, left[n-2] + 1)
        return ans

