        int n = nums.length;
        int[] left = new int[n], right = new int[n];
        Arrays.fill(left, 1); Arrays.fill(right, 1);
        for (int i = 1; i < n; i++)
            if (i > 1 && nums[i]-nums[i-1] == nums[i-1]-nums[i-2]) left[i] = left[i-1] + 1;
        for (int i = n - 2; i >= 0; i--)
            if (i < n - 2 && nums[i+1]-nums[i] == nums[i+2]-nums[i+1]) right[i] = right[i+1] + 1;
        int ans = Arrays.stream(left).max().getAsInt();
        for (int i = 1; i + 1 < n; i++) {
            int L = left[i-1], R = right[i+1];
            boolean hasL = L >= 2, hasR = R >= 2;
            long dl = hasL ? (long)nums[i-1] - nums[i-2] : 0;
            long dr = hasR ? (long)nums[i+2] - nums[i+1] : 0;
            int cand;
            if (hasL && hasR) cand = (dl == dr) ? L + R + 1 : Math.max(L + 1, R + 1);
            else if (hasL) {
                cand = L + 1;
                if ((long)nums[i+1] - nums[i-1] == 2 * dl) cand = Math.max(cand, L + 2);
            } else if (hasR) {
                cand = R + 1;
                if ((long)nums[i+1] - nums[i-1] == 2 * dr) cand = Math.max(cand, R + 2);
            } else cand = 3;
            ans = Math.max(ans, cand);
        }
        ans = Math.max(ans, Math.max(right[1] + 1, left[n-2] + 1));
