    let ans = Math.max(...left);
    for (let i = 1; i + 1 < n; i++) {
        const L = left[i-1], R = right[i+1];
        const hasL = L >= 2, hasR = R >= 2;
        const dl = hasL ? nums[i-1] - nums[i-2] : null;
        const dr = hasR ? nums[i+2] - nums[i+1] : null;
